import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const source=readFileSync(new URL('../assets/scripts/private-navigation.js',import.meta.url),'utf8');
const review=readFileSync(new URL('../reviewer.html',import.meta.url),'utf8');
assert.match(source,/const adminWorkspace=adminPages\.has\(current\)/);
assert.match(source,/if\(!adminWorkspace\)learnerNav\.forEach/);
assert.match(source,/if\(!adminWorkspace\)\{moreNav\.forEach/);
assert.match(source,/if\(!adminWorkspace\)\{const academyLink/);
assert.match(source,/adminWorkspace\?'admin\.html':'account\.html'/);
assert.match(review,/href="admin\.html#admin-learners"/);
assert.doesNotMatch(review,/href="progress\.html" class="review-hero-secondary"/);
console.log('PASS admin-only sidebar, brand and reviewer links; learner navigation excluded');
